import 'package:flutter/material.dart';

void main() => runApp(const ReadingRoomStarter());

class ReadingRoomStarter extends StatelessWidget {
  const ReadingRoomStarter({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false,
    title: 'Reading room onboarding starter',
    themeAnimationDuration: Duration.zero,
    theme: ThemeData(
      useMaterial3: true,
      colorScheme: const ColorScheme.light(
        primary: Color(0xff6a3655), onPrimary: Colors.white,
        secondary: Color(0xff4a586f), onSecondary: Colors.white,
        surface: Color(0xfffcf6ef), onSurface: Color(0xff30262e),
        error: Color(0xffa0202b), onError: Colors.white,
      ),
      scaffoldBackgroundColor: const Color(0xfffcf6ef),
      filledButtonTheme: FilledButtonThemeData(style: FilledButton.styleFrom(minimumSize: const Size(48, 48), padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 16))),
      outlinedButtonTheme: OutlinedButtonThemeData(style: OutlinedButton.styleFrom(minimumSize: const Size(48, 48), padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 16))),
    ),
    home: const ReadingRoomFlow(),
  );
}

class ReadingRoomFlow extends StatefulWidget {
  const ReadingRoomFlow({super.key});
  @override
  State<ReadingRoomFlow> createState() => _ReadingRoomFlowState();
}

class _ReadingRoomFlowState extends State<ReadingRoomFlow> {
  final headingFocus = FocusNode(debugLabel: 'Current flow heading');
  int step = 0;
  bool reminders = false;
  bool addedSample = false;
  static const titles = ['A small place for your reading', 'Choose what stays quiet', 'Your reading list starts here'];

  @override
  void dispose() {
    headingFocus.dispose();
    super.dispose();
  }

  void changeStep(int next) {
    setState(() => step = next);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) headingFocus.requestFocus();
    });
  }

  Widget heading(String text) => Focus(
    focusNode: headingFocus,
    child: Semantics(header: true, liveRegion: true, child: Text(text, style: Theme.of(context).textTheme.headlineMedium?.copyWith(fontFamily: 'serif', height: 1.2))),
  );

  Widget mark() => Semantics(
    image: true,
    label: 'Original decorative study of two open pages',
    child: ExcludeSemantics(child: SizedBox(
      width: 132, height: 104,
      child: Row(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Expanded(child: Container(margin: const EdgeInsets.only(right: 3), decoration: BoxDecoration(color: const Color(0xffdfc9d4), border: Border.all(color: const Color(0xff6a3655), width: 2), borderRadius: const BorderRadius.only(topLeft: Radius.circular(20), bottomLeft: Radius.circular(8))))),
        Expanded(child: Container(margin: const EdgeInsets.only(left: 3), decoration: BoxDecoration(color: const Color(0xffeee3d2), border: Border.all(color: const Color(0xff6a3655), width: 2), borderRadius: const BorderRadius.only(topRight: Radius.circular(20), bottomRight: Radius.circular(8))))),
      ]),
    )),
  );

  Widget onboarding() => Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
    Text('Step ${step + 1} of 2', style: const TextStyle(color: Color(0xff665360))),
    const SizedBox(height: 24),
    mark(),
    const SizedBox(height: 32),
    heading(titles[step]),
    const SizedBox(height: 16),
    Text(step == 0
      ? 'Collect a few things you want to read, without a crowded feed or a score to chase. This original demo asks for no account or personal information.'
      : 'Decide whether a reminder belongs in your routine. This choice changes a local preference only; notification permissions and delivery are not implemented.'),
    const SizedBox(height: 24),
    if (step == 1) ...[
      CheckboxListTile(
        contentPadding: EdgeInsets.zero,
        controlAffinity: ListTileControlAffinity.leading,
        title: const Text('Include a gentle reading reminder'),
        subtitle: const Text('Optional, off by default. No notification will be sent.'),
        value: reminders,
        onChanged: (value) => setState(() => reminders = value ?? false),
      ),
      const SizedBox(height: 24),
    ],
    Wrap(spacing: 12, runSpacing: 12, children: [
      FilledButton(onPressed: () => changeStep(step + 1), child: Text(step == 0 ? 'Continue' : 'Open demo reading list')),
      if (step == 1) OutlinedButton(onPressed: () => changeStep(0), child: const Text('Back')),
      if (step == 0) OutlinedButton(onPressed: () => changeStep(2), child: const Text('Skip introduction')),
    ]),
  ]);

  Widget readingList() => Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
    const Text('READING ROOM / LOCAL DEMO'),
    const SizedBox(height: 24),
    heading(titles[2]),
    const SizedBox(height: 16),
    Text(reminders ? 'Reminder preference selected. This demo sends nothing.' : 'Reminders are off. Nothing is scheduled.'),
    const SizedBox(height: 32),
    if (!addedSample) ...[
      mark(),
      const SizedBox(height: 24),
      const Text('Nothing on the shelf yet', style: TextStyle(fontSize: 22, fontWeight: FontWeight.w600)),
      const SizedBox(height: 12),
      const Text('An empty list is a starting point, not an error. Add one fictional reading prompt to see how an item could look.'),
      const SizedBox(height: 24),
      FilledButton(onPressed: () => setState(() => addedSample = true), child: const Text('Add a sample prompt')),
    ] else ...[
      Semantics(liveRegion: true, child: const Text('One sample prompt added. No content was downloaded.')),
      const SizedBox(height: 16),
      Container(
        width: double.infinity,
        padding: const EdgeInsets.all(20),
        decoration: BoxDecoration(border: Border.all(color: const Color(0xff8a7582)), borderRadius: BorderRadius.circular(6)),
        child: const Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('Notice one useful detail', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w600)),
          SizedBox(height: 12),
          Text('Sample writing prompt: describe an ordinary object, then explain the small decision that makes it useful.'),
          SizedBox(height: 12),
          Text('Original placeholder copy · not an external article'),
        ]),
      ),
      const SizedBox(height: 20),
      OutlinedButton(onPressed: () => setState(() => addedSample = false), child: const Text('Remove sample prompt')),
    ],
    const SizedBox(height: 32),
    OutlinedButton(onPressed: () { setState(() { reminders = false; addedSample = false; }); changeStep(0); }, child: const Text('Restart demo')),
  ]);

  @override
  Widget build(BuildContext context) => Scaffold(body: SafeArea(child: FocusTraversalGroup(
    policy: ReadingOrderTraversalPolicy(),
    child: LayoutBuilder(builder: (context, constraints) => SingleChildScrollView(
      padding: EdgeInsets.all(constraints.maxWidth < 400 ? 20 : 32),
      child: Center(child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 600),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          step < 2 ? onboarding() : readingList(),
          const SizedBox(height: 40),
          const Divider(color: Color(0xff8a7582)),
          const SizedBox(height: 12),
          const Text('Starter UI only. State is in memory; there is no storage, authentication, notification service, or analytics.', style: TextStyle(color: Color(0xff665360))),
        ]),
      )),
    )),
  )));
}
